const $=id=>document.getElementById(id), icon=name=>`<i data-lucide="${name}"></i>`, fmt=n=>Math.floor(n).toLocaleString('en-US');
const seconds=ms=>`${Math.max(0,Math.ceil(ms/1000))}s`;
