let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw new Error('unavailable');}};}
const api=new Connection();let syncEpoch=0,features,lastServerTime=0,worldSignature='',polling=false,battleId=null,selectedSpell='thunder';const shownResults=new Set();
let currentRealm='home',capitalView=null,capitalLeader=false,extensions,quality,raidUI,villageUI;
function village(){if(currentRealm==='capital'&&capitalView)return capitalView;X.ensure(state);if(currentRealm==='builder'){state.expansion.builder.gems=state.gems;return state.expansion.builder;}return state;}
let placementBusy=false;
let state=loadState(storage),world,selected=null,placement=null,battle=null,selectedTroop='guardian',spellMode=false,modalKind='',saveFailed=false,lastUI=0,lastSave=0,hovered=null;
const modal=$('modal');let audioContext;

function save(){if(api.online){try{storage.setItem('emberfall.preferences',JSON.stringify(state.settings));}catch{}return;}try{storage.setItem(SAVE_KEY,JSON.stringify(state));}catch{if(!saveFailed){toast('This browser cannot save progress. Keep this tab open to continue.',true);saveFailed=true;}}}
function worldSync(force=false){
 if(!world)return;world.setTerritory(village(),battle);world.setVillageBanner(battle?battle.bannerCode:village().bannerCode||village().flags?.[0]?.code);world.setFlags(battle?battle.flags||[]:village().flags||[]);if(world.placing){world.placing.state=village();world.updatePlacement(world.placing.x,world.placing.z);}world.setObstacles(village().obstacles||[]);world.setVillageHeroes(village().heroes||{},!!battle,village().buildings);world.setCampArmy(village(),!!battle);
 const list=battle?battle.buildings:village().buildings;const sig=(battle?'battle:':currentRealm+':')+JSON.stringify(list.map(b=>[b.id,b.type,b.level,b.x,b.z,b.rotation,!!b.finishAt]));
 if(sig!==worldSignature||force){worldSignature=sig;world.rebuild(list,!!battle);world.setVillageBanner(battle?battle.bannerCode:village().bannerCode||village().flags?.[0]?.code);if(battle){world.setBattleBounds(battle.bounds);for(const u of battle.units)world.addUnit(u);}}
 if(battle){for(const u of battle.units)if(!world.unitMap.has(u.id))world.addUnit(u);world.updateBattle(battle);}else{for(const c of world.coins)c.b=village().buildings.find(b=>b.id===c.b.id)||c.b;for(const b of village().buildings){const m=world.buildingMap.get(b.id);if(m)m.userData.building=b;}}
}
function applyResponse(data){
 if(data.user&&data.user.id!==state.playerId){syncEpoch++;if(state.playerId){lastServerTime=0;if(data.battle===null){battle=null;battleId=null;$('battle-hud').hidden=true;$('battle-top').hidden=true;$('village-hud').hidden=false;$('village-rail').hidden=false;currentRealm='home';}}state.playerId=data.user.id;}if(data.serverTime&&data.serverTime<lastServerTime)return;lastServerTime=data.serverTime||lastServerTime;
 const priorSelected=selected?[selected.level,selected.finishAt].join(':'):null;
 if(data.state){for(const o of state.obstacles||[])if(o.finishAt&&!data.state.obstacles.some(n=>n.id===o.id)){toast(o.gemReward?'Obstacle cleared · +'+o.gemReward+' gems':'Obstacle cleared.');world?.burst(o.x,1,o.z,0xa7db91,12);}const prefs=state.settings,playerId=state.playerId;state=data.state;state.settings=prefs;state.playerId=playerId;}
 if(data.user)api.user=data.user;if(data.result?.capital)capitalView=data.result.capital;
 if(data.battle){battle=data.battle;battleId=data.battleId||battle.id;battle.id=battleId;showBattleHUD();}
 if(selected)selected=village().buildings.find(b=>b.id===selected.id)||null;
 worldSync();if(selected&&!battle){world.setSelection(selected);if(!placement&&priorSelected!==[selected.level,selected.finishAt].join(':'))selectBuilding(selected);}renderHUD();if(battle){renderDeploy();if(battle.ended&&battle.result)finishBattle();}
}
async function sync(){if(!api.online||polling)return;polling=true;const epoch=syncEpoch;try{const data=await api.request(battleId?'/battle?id='+encodeURIComponent(battleId):'/state');if(epoch===syncEpoch){if(currentRealm==='capital'&&!battle){const f=await api.request('/frontiers');if(f.world)capitalView=f.world.village;else currentRealm='home';}applyResponse(data);}}catch(e){toast(e.message,true);}finally{polling=false;}}
async function mutate(action){
 if(!action.realm&&['build','move','upgrade','train','collect','research','clear','skip','brew','claim','train-batch','army-preset-save','army-preset-train','wall-upgrade'].includes(action.type))action={...action,realm:currentRealm};
 let r;if(api.online){r=await api.command({...action,...(action.type.startsWith('battle-')?{battleId}: {})});applyResponse(r);}
 else{let result;if(action.type==='battle-deploy')result=M.deploy(state,battle,action.troop,action.x,action.z);else if(action.type==='battle-hero')result=M.deployHero(state,battle,action.hero,action.x,action.z);else if(action.type==='battle-spell')result=M.castSpell(state,battle,action.spell,action.x,action.z);else if(action.type==='battle-siege')result=X.deploySiege(state,battle,action.siege,action.x,action.z);else if(action.type==='battle-ability')result=M.heroAbility(battle,action.hero);else result=M.applyAction(state,action);if(result.error)throw new Error(result.error);r={state,result};if(battle)R.startAttack(state,battle);save();worldSync();renderHUD();if(battle)renderDeploy();}
 return r.result||{};
}
function showBattleHUD(){if(!battle)return;$('village-hud').hidden=true;$('village-rail').hidden=true;$('battle-hud').hidden=false;$('battle-top').hidden=false;$('enemy-name').textContent=battle.enemy.name;$('spell-button').disabled=battle.ended;}
function toast(message,bad=false){const div=document.createElement('div');div.className='toast'+(bad?' bad':'');div.textContent=message;$('toasts').appendChild(div);while($('toasts').children.length>3)$('toasts').firstChild.remove();setTimeout(()=>div.remove(),4000);}
function sound(kind){
  if(!state.settings.sound)return;
  try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime;
    const tones={click:[360],coin:[660,880,1100],build:[220,330,440],train:[440,554,660],win:[392,494,587,784],hit:[110],spell:[145,280,530],bad:[150,120]};
    for(const [i,f] of (tones[kind]||tones.click).entries()){const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=['hit','spell'].includes(kind)?'triangle':'sine';osc.frequency.setValueAtTime(f,now+i*.085);if(kind==='hit')osc.frequency.exponentialRampToValueAtTime(50,now+.12);gain.gain.setValueAtTime(0,now+i*.085);gain.gain.linearRampToValueAtTime(kind==='hit'?.026:.05,now+i*.085+.015);gain.gain.exponentialRampToValueAtTime(.001,now+i*.085+.17);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.085);osc.stop(now+i*.085+.19);}
  }catch{}
}
function showModal(kind,html){document.getElementById('kingdom-menu')?.close();modalKind=kind;$('modal-content').innerHTML=html;if(!modal.open)modal.showModal();icons();}
function closeModal(){modal.close();modalKind='';}
function header(eyebrow,title){return `<div class="modal-header"><div><small>${eyebrow}</small><h2>${title}</h2></div><button class="close-btn" data-action="close" aria-label="Close dialog">${icon('x')}</button></div>`;}
function renderHUD(){
  raidUI?.tick();villageUI?.sync();
  $('gold-value').textContent=fmt(village().gold);$('elixir-value').textContent=fmt(village().elixir);$('glory-value').textContent=fmt(village().glory);$('gold-fill').style.width=Math.min(100,village().gold/capacity(village())*100)+'%';$('elixir-fill').style.width=Math.min(100,village().elixir/capacity(village())*100)+'%';
  $('gems-value').textContent=fmt(state.gems||0);$('dark-value').textContent=fmt(state.dark||0);$('player-level').textContent=hallLevel(village());$('rank').textContent=village().glory>=250?'Ember sovereign':village().glory>=100?'Highland guardian':village().glory>=30?'Wilds explorer':'Wandering clan';
  $('builders').textContent=`${freeBuilders(village())}/${village().builders||2}`;$('army-count').textContent=Object.values(village().army).reduce((a,b)=>a+b,0);$('army-caption').textContent=`${armySize(village().army)} / ${armyCapacity(village())} spaces`;
  const ready=village().buildings.reduce((n,b)=>n+Math.floor(b.stored||0),0);$('collect-amount').textContent=ready?`${fmt(ready)} ready`:'Producing resources';
  const quest=QUESTS.find(q=>!village().claimed.includes(q.id));if(quest){$('quest-title').textContent=quest.title;$('quest-sub').textContent=quest.value(village())>=quest.goal?`Claim ${fmt(quest.reward)} gold` : quest.desc;$('quest-progress').style.width=Math.min(100,quest.value(village())/quest.goal*100)+'%';}else{$('quest-title').textContent='Your legend is growing';$('quest-sub').textContent=`${village().stats.wins} victories in the wilds`;$('quest-progress').style.width='100%';}
  document.querySelector('.land-trigger').hidden=currentRealm!=='home';if(selected&&!battle)updateBuildingTimer();if(modalKind==='army')updateArmyModal();features?.tick(modalKind);extensions?.tick(modalKind);quality?.tick(modalKind);document.querySelector('.chapter h1').textContent=currentRealm==='builder'?'Nightfall':currentRealm==='capital'?'Clan Capital':'Willowmere';$('return-village').hidden=currentRealm==='home';$('collect-button').disabled=currentRealm==='capital';$('train-button').disabled=currentRealm==='capital';$('build-button').disabled=currentRealm==='capital'&&!capitalLeader;$('spells-button').disabled=currentRealm!=='home';
}
function deselect(){selected=null;world?.setSelection(null);$('building-panel').hidden=true;$('building-label').hidden=true;}
function selectBuilding(b){
  if(!b)return;cancelPlacement();selected=b;world.setSelection(b);$('building-panel').hidden=false;const def=TYPES[b.type],cost=upgradeCost(b);
  let specific='';if(producerRate(b))specific=`<div class="stat-row"><span>Production <b>${Math.round(producerRate(b)*60)}/min</b></span><span>Stored <b id="selected-stored">${fmt(b.stored||0)}</b> / ${productionCapacity(b)}</span></div>`;
  else if(b.type==='camp')specific=`<div class="stat-row"><span>Army capacity</span><b>${armySize(village().army)} / ${armyCapacity(village())} spaces</b></div>`;
  else if(b.type==='storage')specific=`<div class="stat-row"><span>Resource capacity</span><b>${fmt(capacity(village()))} each</b></div>`;
  else specific=`<div class="stat-row"><span>Hit points</span><b>${fmt(M.buildingHp(b))}</b></div>`;
  const defense=M.defenseStats(b),nextHp=M.buildingHp({...b,level:Math.min(15,b.level+1)});
  specific+=`<div class="stat-row"><span>HP · ${b.level<15?'next level':'maximum'}</span><b>${fmt(M.buildingHp(b))}${b.level<15?' → '+fmt(nextHp):''}</b></div>`;
  if(defense){const next=M.defenseStats({...b,level:Math.min(15,b.level+1)});specific+=`<div class="stat-row"><span>Defense DPS</span><b>${fmt(defense.damage/defense.rate)}${b.level<15?' → '+fmt(next.damage/next.rate):''}</b></div><div class="stat-row"><span>Range · targets</span><b>${defense.range.toFixed(1)} · ${defense.airOnly?'Air':defense.groundOnly?'Ground':'Air + ground'}</b></div>`;}
  $('building-panel').innerHTML=`<button class="close-btn" data-action="deselect" aria-label="Close building">${icon('x')}</button><div class="building-heading">${icon(def.icon)}<div><h2>${def.name}</h2><small>Level ${b.level}${b.level>1?' · Upgraded':''}</small></div></div><p>${def.desc}</p>${specific}${producerRate(b)||['camp','storage'].includes(b.type)?`<div class="stat-row"><span>Hit points</span><b>${fmt(M.buildingHp(b))}</b></div>`:''}<div id="building-work" ${b.finishAt?'':'hidden'} class="training-queue">${icon('hammer')} <span id="building-timer">${b.constructing?'Building':'Upgrading'} · ${seconds((b.finishAt||0)-Date.now())}</span></div><div class="panel-actions" style="margin-top:14px"><button class="btn btn-gold" id="upgrade-selected" data-action="upgrade" ${b.finishAt||b.level>=15?'disabled':''} style="flex:1">${icon('arrow-up')}${b.level>=15?'Max level':`Upgrade · ${fmt(cost.gold)} ${icon('coins')}`}</button><button class="btn" data-action="move" aria-label="Move building" ${b.finishAt?'disabled':''}>${icon('move')}</button></div>${!b.finishAt&&b.level<15?`<div class="saved-note">${b.type==='wall'?'Instant upgrade · No builder needed':`Also ${fmt(cost.elixir)} elixir · ${cost.time}s construction`}</div>`:''}${producerRate(b)?`<button class="btn btn-full" style="margin-top:10px" data-action="collect-one">${icon('hand-coins')} Collect ${b.type==='mine'?'gold':b.type==='drill'?'dark elixir':'elixir'}</button>`:''}${b.type==='barracks'?`<button class="btn btn-full" style="margin-top:10px" data-action="army">${icon('users')} Train troops</button>`:''}`;
  features?.enhanceBuilding(b);$('building-panel').insertAdjacentHTML('beforeend',`<button class="btn btn-full" style="margin-top:10px" data-village="detail" data-kind="building" data-type="${b.type}" data-level="${b.level}">${icon('scan')} Inspect 3D · Level ${b.level}</button>${b.type==='hall'&&currentRealm==='home'?'<button class="btn btn-full" data-village="land">Across the bridge · New land</button>':''}${b.type==='barracks'?'<button class="btn btn-full" id="barracks-heroes" data-action="heroes">Hero unlocks</button>':''}`);if(b.type==='wall'&&currentRealm!=='capital')$('building-panel').insertAdjacentHTML('beforeend',`<button class="btn btn-full" style="margin-top:10px" data-q="walls" data-id="${b.id}">${icon('brick-wall')}Select walls · Upgrade together</button>`);if(currentRealm==='capital'&&!capitalLeader)for(const el of $('building-panel').querySelectorAll('button[data-action=upgrade],button[data-action=move]'))el.disabled=true;icons();sound('click');
}
function updateBuildingTimer(){
  if(!selected)return;if($('selected-stored'))$('selected-stored').textContent=fmt(selected.stored||0);if(selected.finishAt&&$('building-timer'))$('building-timer').textContent=`${selected.constructing?'Building':'Upgrading'} · ${seconds(selected.finishAt-Date.now())}`;
}
function openBuild(){
  const kinds=currentRealm==='home'?Object.keys(TYPES).filter(t=>!['hall','cottage','flag'].includes(t)):X.BUILDER_TYPES;
  showModal('build',header('A KINGDOM, ONE STONE AT A TIME','Build your village')+`<div class="modal-body"><p class="modal-intro">Choose a building, then tap an empty space in your village. ${freeBuilders(village())} of ${village().builders} builders available.</p>${currentRealm==='home'?'<div class="expansion-tabs"><button class="btn btn-gold" data-village="land">Across the bridge</button><button class="btn btn-gold" data-village="flags">Country flags</button></div>':''}<div class="card-grid">${kinds.map(type=>{const d=TYPES[type],count=village().buildings.filter(b=>b.type===type).length;return `<article class="shop-card"><span class="card-badge">${count} / ${d.max}</span>${modelPortrait('building',type,1,'shop-model')}<h3>${d.name}</h3><p>${d.desc}</p><div class="card-meta"><span>Level 1</span><span>${icon('heart')}${fmt(M.buildingHp({type,level:1}))} HP</span><span>${icon('timer')}${d.time}s</span>${d.elixir?`<span>${icon('droplets')}${d.elixir}</span>`:''}</div><button class="btn btn-gold" data-action="place" data-type="${type}" ${count>=d.max||village().gold<d.gold||village().elixir<d.elixir||(type!=='wall'&&freeBuilders(village())<1)||hallLevel(village())<(d.unlock||1)?'disabled':''}>${hallLevel(village())<(d.unlock||1)?'Town Hall '+d.unlock:count>=d.max?'Limit reached':`${icon('coins')}${fmt(d.gold)} · Build`}</button></article>`;}).join('')}</div>${currentRealm!=='capital'?`<button class="btn btn-full" data-q="walls" style="margin-top:16px">${icon('brick-wall')}Manage wall upgrades</button>`:''}</div>`);
}
