function updateArmyModal(){
  if(!$('army-capacity'))return;$('army-capacity').innerHTML=`${icon('tent')}${armySize(village().army)+queueSize(village())} / ${armyCapacity(village())} army spaces${queueSize(village())?` · ${queueSize(village())} training`:''}`;
  for(const [type,d] of Object.entries(TROOPS)){const btn=$('train-'+type);if(btn)btn.disabled=village().elixir<d.cost||armySize(village().army)+queueSize(village())+d.space>armyCapacity(village())||!village().buildings.some(b=>b.type==='barracks'&&!b.finishAt);$('owned-'+type).textContent=(village().army[type]||0)+' ready';if(btn&&!M.troopUnlocked(village(),type)){btn.disabled=true;btn.textContent='Barracks level '+(d.unlock||1);}}
  if($('training-speed'))$('training-speed').innerHTML=village().queue.length?`<button class="btn btn-small" data-v2="skip" data-kind="training" style="margin-top:12px">${icon('gem')}${M.skipCost(village().queue[0].finishAt)} · Finish next troop</button>`:'';
  $('queue-items').innerHTML=village().queue.length?village().queue.map(q=>`<span class="queue-item">${icon(TROOPS[q.type].icon)}${TROOPS[q.type].name} · ${seconds(q.finishAt-Date.now())}</span>`).join(''):'Your barracks is ready. Choose a troop above.';icons();
}
function openCampaign(){
  if(currentRealm==='builder'){startBattle(0,null,{mode:'builder'});return;}if(currentRealm==='capital'){extensions.frontiers('capital');return;}
  const canRaid=armySize(village().army)>0||Object.values(village().heroes).some(h=>h.level&&!h.finishAt&&!(h.recoverAt>Date.now()));const unlocked=Object.keys(village().cleared).length?Math.max(...Object.keys(village().cleared).map(Number))+1:0;const start=Math.max(0,unlocked-2);const levels=Array.from({length:Math.min(4,unlocked-start+2)},(_,i)=>start+i);
  showModal('campaign',`<div class="campaign-art" style="background-image:url('/assets/campaign.webp')"><button class="close-btn" data-action="close" aria-label="Close campaign">${icon('x')}</button><div class="campaign-art-title"><small>BEYOND THE VILLAGE GATES</small><h2>Conquer the wilds</h2></div></div><div class="modal-body"><p class="modal-intro">Scout a stronghold, deploy your army, and bring the spoils home.</p><p class="capacity-note">${icon('users')}${Object.values(village().army).reduce((a,b)=>a+b,0)} troops ready · ${armySize(village().army)} army spaces</p><div class="enemy-list">${levels.map(index=>{const e=enemyDef(index),locked=index>unlocked;return `<div class="enemy-row"><span class="enemy-number">${String(index+1).padStart(2,'0')}</span><div class="enemy-data"><h3>${e.name}</h3><small>${locked?'Win the previous battle to unlock':e.difficulty}</small><div class="enemy-loot"><span>${icon('coins')}${fmt(e.gold)}</span><span>${icon('droplets')}${fmt(e.elixir)}</span><span>${icon('trophy')}${e.glory}</span></div></div>${village().cleared[index]?`<span class="enemy-cleared" aria-label="${village().cleared[index]} stars">${'★'.repeat(village().cleared[index])}${'☆'.repeat(3-village().cleared[index])}</span>`:''}<button class="btn ${locked?'':'btn-gold'}" data-action="scout" data-index="${index}" ${locked||!canRaid?'disabled':''}>${icon(locked?'lock-keyhole':'swords')}${locked?'Locked':'Scout'}</button></div>`;}).join('')}</div>${!canRaid?`<button class="btn btn-gold btn-full" style="margin-top:16px" data-action="army">${icon('users')} Train an army first</button>`:''}<p class="guide-foot">Earn a star for 50% destruction, one for the Town Hall, and one for total destruction. One star unlocks the next stronghold.</p></div>`);
}
function openQuests(){showModal('quests',header('THE PATH TO GREATNESS','Village quests')+`<div class="modal-body"><div class="quest-list">${QUESTS.map(q=>{const completed=village().claimed.includes(q.id),ready=q.value(village())>=q.goal;return `<div class="quest-row">${icon(completed?'circle-check':q.icon)}<div><strong>${q.title}</strong><small>${q.desc} · ${Math.min(q.goal,q.value(village()))}/${q.goal}</small></div><button class="btn ${ready&&!completed?'btn-gold':''}" data-action="claim" data-id="${q.id}" ${completed||!ready?'disabled':''}>${completed?'Claimed':`${icon('coins')}${fmt(q.reward)}`}</button></div>`;}).join('')}</div></div>`);}
function openGuide(){showModal('guide',header('WELCOME, CHIEF','Your kingdom awaits')+`<div class="modal-body"><div class="guide-steps"><div class="guide-step"><span class="step-number">1</span><div><strong>Build & collect · ရွာတည်ဆောက်မယ်</strong><p>Build ကိုနှိပ်၊ အဆောက်အဦးရွေးပြီး မြေကွက်လွတ်ပေါ်မှာ ပုံစံကို ရွှေ့ကြည့်ပါ။ အစိမ်းရောင်ဖြစ်ရင် Build here ကိုနှိပ်ပြီး အတည်ပြုပါ။ ရွှေနဲ့ Elixir ရဖို့ Collect ကိုနှိပ်ပါ။ အဆောက်အဦးပေါ်နှိပ်ပြီး Upgrade လုပ်နိုင်ပါတယ်။</p></div></div><div class="guide-step"><span class="step-number">2</span><div><strong>Raise an army · စစ်သားလေ့ကျင့်မယ်</strong><p>Army ထဲမှာ စစ်သားလေ့ကျင့်ပါ။ Guardian က ရှေ့တန်း၊ Ranger က အဝေးပစ်၊ Stone Giant က ခံနိုင်ရည်များပြီး ရန်သူ့ကာကွယ်ရေးကို အရင်တိုက်ပါတယ်။</p></div></div><div class="guide-step"><span class="step-number">3</span><div><strong>Raid the wilds · တိုက်ပွဲဝင်မယ်</strong><p>Battle → Scout ကိုနှိပ်ပါ။ စစ်သားအမျိုးအစားရွေးပြီး အနီရောင်ဘောင်အပြင်မှာ နှိပ်ချပါ။ Thunder ကိုရွေးပြီး ရန်သူ့အဆောက်အဦးပေါ် နှိပ်ရင် မိုးကြိုးပစ်နိုင်ပါတယ်။</p></div></div><div class="guide-step"><span class="step-number">4</span><div><strong>Explore · မြင်ကွင်းရွှေ့မယ်</strong><p>ဖိဆွဲပြီး မြင်ကွင်းရွှေ့ပါ။ လက်နှစ်ချောင်းနဲ့ ချဲ့/ချုံ့နိုင်ပါတယ်။ ကွန်ပျူတာမှာ mouse wheel၊ + / − နဲ့ မြင်ကွင်းချဲ့/ချုံ့၊ H နဲ့ အလယ်ပြန်ထားနိုင်ပါတယ်။</p></div></div></div><p class="guide-foot">Campaign + server player raids · Your current save mode appears in Settings. Deployed troops are spent in each raid. Resources accumulate for up to 8 hours away, limited by each building’s storage.</p><button class="btn btn-gold btn-full" data-action="close">${icon('flag')} Back to the village</button></div>`);}
function openSettings(){showModal('settings',header('MAKE YOURSELF AT HOME','Game settings')+`<div class="modal-body"><div class="settings-row"><div><strong>Sound effects</strong><small>Construction, coins, and battle sounds</small></div><button class="btn" data-action="sound">${icon(state.settings.sound?'volume-2':'volume-x')}${state.settings.sound?'On':'Off'}</button></div><div class="settings-row"><div><strong>3D graphics</strong><small>Ultra HD uses more battery. Smooth suits older phones.</small></div><select id="graphics-quality" aria-label="3D graphics quality">${Object.entries(GRAPHICS).map(([id,p])=>`<option value="${id}" ${graphicsProfile(state.settings.quality)===id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="settings-row"><div><strong>How to play</strong><small>မြန်မာလို ကစားနည်းဖတ်ရန်</small></div><button class="btn" data-action="guide">${icon('book-open')} Guide</button></div><p class="settings-footer">Emberfall · Kingdoms at War<br>${api.online?'Server connected · Your village is saved in the server database.':saveFailed?'Saving is unavailable in this browser.':'Standalone mode · Your village is saved on this device.'}<br>Gold & elixir capacity: ${fmt(capacity(village()))} each.<br>${api.online?'Use an account to access your village on other devices.':'Clearing browser data removes your standalone village.'}</p><button class="btn btn-full" data-v2="account">Village account · Google / Facebook</button>${nativeApp()?'<button class="btn btn-full" data-action="server">Server & app</button>':''}<button class="btn btn-full" data-action="close" style="margin-top:10px">Continue playing</button></div>`);}
async function doCollect(id){try{const r=await mutate({type:'collect',id});if(r.gold||r.elixir){toast(`${r.gold?'+'+fmt(r.gold)+' gold':''}${r.gold&&r.elixir?' · ':''}${r.elixir?'+'+fmt(r.elixir)+' elixir':''}`);sound('coin');for(const b of village().buildings)if((!id||id===b.id)&&producerRate(b))world.burst(b.x,2,b.z,b.type==='mine'?0xe7c467:0xcfa1e3,9);}else toast('Resources collected. Upgrade your stores if they are full.');}catch(e){toast(e.message,true);}}
async function startBattle(index,defender,extra={}){
 try{syncEpoch++;closeModal();cancelPlacement();deselect();if(api.online){const r=await api.command({type:'battle-start',index,defender,...extra});applyResponse(r);}else{if((!extra.mode||extra.mode==='match')&&armySize(village().army)<1&&!Object.values(state.heroes).some(h=>h.level&&!h.finishAt&&!(h.recoverAt>Date.now()))){toast('Train your army before battle.',true);return;}const modeResult=extra.mode==='match'?{battle:R.createBotBattle(state)}:extra.mode?X.createModeBattle(state,extra.mode):null;if(modeResult?.error)throw Error(modeResult.error);battle=modeResult?.battle||createBattle(state,index);battle.id=requestId();battleId=battle.id;worldSync(true);}
 selectedTroop=Object.keys(TROOPS).find(k=>battle.remaining[k]>0)||'guardian';spellMode=false;world.recenter();if((battle.bounds||8.7)>10)world.setZoom(.85);showBattleHUD();renderDeploy();sound('build');toast('Scout the defenses. Deploy outside red footprints or on green cleared tiles.');
 }catch(e){toast(e.message,true);}
}
function renderDeploy(){
 if(!battle)return;$('deploy-cards').innerHTML=Object.entries(TROOPS).filter(([k])=>(battle.remaining[k]||0)+(battle.deployed[k]||0)>0).map(([type,d])=>`<button class="deploy-card ${selectedTroop===type&&!spellMode?'selected':''}" data-action="troop" data-type="${type}" aria-label="Deploy ${d.name}, ${battle.remaining[type]||0} remaining" ${!(battle.remaining[type]>0)?'disabled':''}><b>${battle.remaining[type]||0}</b>${modelPortrait('troop',type,X.wallet(state,battle).research?.[type]||1,'deploy-model')}<span>${d.name}</span></button>`).join('')+(features?.heroCards(battle,selectedTroop)||'')+(extensions?.siegeCards(battle,selectedTroop)||'');icons();
 const troop=TROOPS[selectedTroop]||M.HEROES[selectedTroop]||X.SIEGE[selectedTroop];$('deploy-instruction').textContent=spellMode?'Tap the battlefield to cast '+M.SPELLS[selectedSpell].name:troop?'Tap outside red footprints or on a green cleared tile '+troop.name:'Your army is fighting.';
 $('spell-count').textContent=Object.values(battle.spellStock||{}).reduce((a,b)=>a+b,0)+' spells';$('spell-button').querySelector('strong').textContent='Spells';
}
function finishBattle(){
  if(!battle||shownResults.has(battle.id))return;const r=battle.result||settleBattle(state,battle);shownResults.add(battle.id);save();renderHUD();sound(r.won?'win':'bad');spellMode=false;
  showModal('result',`<div class="result-body"><span class="result-eyebrow">${escapeHtml(battle.enemy.name)}</span><h2>${r.stars===3?'Total victory':r.won?'Victory is yours':r.percent?'A hard-fought battle':'Live to fight again'}</h2><div class="result-stars" aria-label="${r.stars} of 3 stars">${'★'.repeat(r.stars)}${'☆'.repeat(3-r.stars)}</div><p>${r.practice?'Training complete · No resources spent<br>':''}${r.percent}% destruction${r.won?' · Your legend grows.':' · Regroup, train, and return stronger.'}</p><div class="result-loot"><div>${icon('coins')}${fmt(r.gold)}</div><div>${icon('droplets')}${fmt(r.elixir)}</div><div>${icon('fuel')}${fmt(r.dark)}</div><div>${icon('trophy')}${r.glory}</div></div><p>${r.ore?'+'+r.ore+' ore · ':''}${r.capitalGold?'+'+r.capitalGold+' capital gold · ':''}${r.medals?'+'+r.medals+' raid medals':''}</p><button class="btn btn-gold" data-action="home">${icon('house')} Return home</button><p class="guide-foot">${Object.values(battle.deployed).reduce((a,b)=>a+b,0)} troops deployed · ${Object.values(battle.remaining).reduce((a,b)=>a+b,0)} troops return from reserve<br>Loot is added up to your village’s storage capacity.</p></div>`);
}
async function home(){
 try{syncEpoch++;if(api.online&&battle&&!battle.settled)await api.command({type:'battle-end',battleId});closeModal();battle=null;battleId=null;worldSignature='';worldSync(true);world.recenter();$('village-hud').hidden=false;$('village-rail').hidden=false;$('battle-hud').hidden=true;$('battle-top').hidden=true;if(api.online)await sync();renderHUD();}catch(e){toast(e.message,true);}
}
async function handleClick({point,buildingId,obstacleId,heroType,campUnit,flagId}){
 if(!point||modal.open)return;
 if(battle){if(battle.ended)return;try{if(spellMode){await mutate({type:'battle-spell',spell:selectedSpell,x:point.x,z:point.z});world.spellEffect(selectedSpell,point.x,point.z);sound('spell');spellMode=false;$('spell-button').classList.remove('active');renderDeploy();return;}
  await mutate(X.SIEGE[selectedTroop]?{type:'battle-siege',siege:selectedTroop,x:point.x,z:point.z}:M.HEROES[selectedTroop]?{type:'battle-hero',hero:selectedTroop,x:point.x,z:point.z}:{type:'battle-deploy',troop:selectedTroop,x:point.x,z:point.z});sound('click');
 }catch(e){toast(e.message,true);}return;}
 if(placement){world.updatePlacement(point.x,point.z);world.placing.pinned=true;return;}
 if(flagId){deselect();villageUI.flagSelected(flagId);return;}if(heroType){deselect();extensions.selectedHero=heroType;features.heroes();return;}if(campUnit){openArmy();return;}
 if(obstacleId){deselect();features.obstacle(obstacleId);return;}
 if(buildingId)selectBuilding(village().buildings.find(b=>b.id===buildingId));else deselect();
}
async function confirmPlacement(){
 const p=world.placing;if(!p||!p.valid||placementBusy)return;const btn=$('confirm-placement');btn.disabled=true;placementBusy=true;
 try{const action=p.type==='flag'?(p.movingId?{type:'flag-move',id:p.movingId,x:p.x,z:p.z}:{type:'flag-buy',code:placement.code,x:p.x,z:p.z}):p.movingId?{type:'move',id:p.movingId,x:p.x,z:p.z,rotation:p.rotation}:{type:'build',building:p.type,x:p.x,z:p.z,rotation:p.rotation};const result=await mutate(action);
  if(p.type==='flag'){cancelPlacement();worldSync(true);toast(p.movingId?'Flag moved.':'Flag placed.');}
  else if(p.type==='wall'&&!p.movingId){worldSync(true);world.setPlacement('wall',village());const next=M.nextWallSpot(village(),p.x,p.z,p.rotation);if(next)world.updatePlacement(next.x,next.z);world.placing.rotation=p.rotation;
   $('confirm-placement').innerHTML=icon('plus')+' Add wall · '+TYPES.wall.gold; $('cancel-placement').textContent='Done';
   if(village().gold<TYPES.wall.gold||village().buildings.filter(b=>b.type==='wall').length>=TYPES.wall.max){cancelPlacement();toast('Wall building finished.');}
  }else{cancelPlacement();worldSync(true);const building=result.building||village().buildings.find(b=>b.id===p.movingId);if(building)selectBuilding(village().buildings.find(b=>b.id===building.id));toast(p.movingId?'Building moved.':'Construction started.');}
  sound('build');icons();
 }catch(e){toast(e.message,true);}finally{placementBusy=false;btn.disabled=!world.placing?.valid;}
}

function battleEvent(event){
  if(event.kind==='hit'){const {unit:u,target:b}=event;if(u.hero)world.damageLabel(event.damage,b.x,2.5,b.z);if(event.ranged)world.projectile(u.x,.9,u.z,b.x,1.1,b.z,0xf2d799);else world.burst(u.x+(b.x-u.x)*.33,.7,u.z+(b.z-u.z)*.33,0xebc477,2);if(Math.random()<.18)sound('hit');}
  else if(event.kind==='defend'){const {building:b,unit:u}=event;world.projectile(b.x,b.type==='tower'?3:1.4,b.z,u.x,.6,u.z,b.type==='tower'?0xe9cd8c:0x534c37);}
  else if(event.kind==='end'){if(!api.online)finishBattle();}else if(event.kind==='trap')world.burst(event.building.x,.6,event.building.z,0xeaaa60,22);
}
function frame(dt,t){
  villageUI?.position();
  if(battle){if(!battle.ended)stepBattle(battle,dt,battleEvent);for(const u of battle.units)if(!world.unitMap.has(u.id))world.addUnit(u);world.updateBattle(battle);const left=Math.max(0,Math.ceil(battle.duration-battle.elapsed));$('battle-time').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;$('destruction').textContent=battle.stats.percent+'%';$('battle-stars').textContent='★'.repeat(battle.stats.stars)+'☆'.repeat(3-battle.stats.stars);}
  const now=Date.now();if(t-lastUI>.35){lastUI=t;if(!battle)world.setVillageHeroes(village().heroes||{},false,village().buildings);const events=api.online?[]:advance(state,now);if(!api.online&&currentRealm==='builder')worldSync();if(events.some(e=>e.kind==='building')){if(!battle){worldSync(true);if(selected)selectBuilding(selected);}for(const e of events.filter(e=>e.kind==='building'))toast(`${TYPES[e.building.type].name} ready · Level ${e.building.level}`);sound('build');save();}if(events.some(e=>['hero','troop'].includes(e.kind)))worldSync();if(events.some(e=>e.kind==='troop')){if(modalKind!=='army')toast(`${events.filter(e=>e.kind==='troop').length} troop${events.filter(e=>e.kind==='troop').length>1?'s':''} ready at camp.`);sound('train');}if(events.some(e=>['obstacle','regrow'].includes(e.kind))){worldSync(true);for(const e of events.filter(e=>e.kind==='obstacle'))toast(e.gems?'Obstacle cleared · +'+e.gems+' gems':'Obstacle cleared.');}renderHUD();}
  if(t-lastSave>(api.online?(battle ? 0.7 : 3):8)){lastSave=t;if(api.online)sync();else save();}
  if(!battle&&!placement&&!modal.open){const b=selected||village().buildings.find(b=>b.id===hovered);if(b){const p=world.project(b);$('building-label').hidden=false;$('building-label').style.left=p.x+'px';$('building-label').style.top=p.y+'px';$('building-label').textContent=`${TYPES[b.type].name} · Lv. ${b.level}`;}else $('building-label').hidden=true;}else $('building-label').hidden=true;
}
function setRealm(realm){if(battle){toast('Return from battle first.',true);return;}currentRealm=realm;closeModal();cancelPlacement();deselect();worldSync(true);world.recenter();renderHUD();toast(realm==='builder'?'Builder Base · Your second village':'Home village');}
function setCapital(villageData,leader){capitalView=villageData;capitalLeader=leader;setRealm('capital');}
function toggleSound(){state.settings.sound=!state.settings.sound;$('sound-button').innerHTML=icon(state.settings.sound?'volume-2':'volume-x');$('sound-button').setAttribute('aria-label',state.settings.sound?'Mute sound':'Enable sound');icons();save();sound('click');if(modalKind==='settings')openSettings();}

document.addEventListener('click',async e=>{
  const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;try{
  if(action==='close'){if(modalKind==='result')home();else closeModal();}
  else if(action==='deselect')deselect();
  else if(action==='place')startPlacement(button.dataset.type);
  else if(action==='select-owned'){closeModal();selectBuilding(village().buildings.find(b=>b.id===button.dataset.id));}
  else if(action==='army')openArmy();
  else if(action==='heroes')features.heroes();
  else if(action==='campaign')openCampaign();
  else if(action==='train'){await mutate({type:'train',troop:button.dataset.type});updateArmyModal();sound('click');}
  else if(action==='upgrade'){const id=selected.id,isWall=selected.type==='wall';await mutate({type:'upgrade',id});worldSync(true);selectBuilding(village().buildings.find(b=>b.id===id));sound('build');toast(isWall?'Wall upgraded.':'Upgrade started.');}
  else if(action==='move'&&selected)startPlacement(selected.type,selected.id);
  else if(action==='collect-one'&&selected)doCollect(selected.id);
  else if(action==='scout')startBattle(Number(button.dataset.index));
  else if(action==='troop'){selectedTroop=button.dataset.type;spellMode=false;$('spell-button').classList.remove('active');renderDeploy();sound('click');}
  else if(action==='home')home();
  else if(action==='claim'){await mutate({type:'claim',id:button.dataset.id});openQuests();sound('coin');toast('Quest reward collected.');}
  else if(action==='sound')toggleSound();
  else if(action==='quality'){state.settings.quality=state.settings.quality==='low'?'high':'low';world.setQuality(state.settings.quality!=='low');save();openSettings();}
  else if(action==='server')chooseServer();
  else if(action==='guide')openGuide();
  else if(action==='confirm-retreat'){closeModal();if(api.online){await mutate({type:'battle-end'});}else finishBattle();}
}catch(e){toast(e.message,true);}
});
$('build-button').addEventListener('click',()=>{cancelPlacement();openBuild();});
$('train-button').addEventListener('click',()=>{cancelPlacement();openArmy();});
$('hero-roster-button').addEventListener('click',()=>features.heroes());
$('attack-button').addEventListener('click',()=>{cancelPlacement();currentRealm==='home'?raidUI.menu():openCampaign();});
$('collect-button').addEventListener('click',()=>doCollect());
$('quest-button').addEventListener('click',openQuests);
$('player-button').addEventListener('click',()=>features?.account());
$('settings-button').addEventListener('click',openSettings);
$('sound-button').addEventListener('click',toggleSound);
$('zoom-in').addEventListener('click',()=>world.setZoom(world.zoom*1.17));
$('zoom-out').addEventListener('click',()=>world.setZoom(world.zoom/1.17));
$('recenter').addEventListener('click',()=>world.recenter());
$('cancel-placement').addEventListener('click',cancelPlacement);
$('spell-button').addEventListener('click',()=>features.battleSpells());
$('confirm-placement').addEventListener('click',confirmPlacement);
$('rotate-placement').addEventListener('click',()=>world.rotatePlacement());
$('retreat-button').addEventListener('click',()=>{if(!battle)return;if(!battle.started){home();return;}showModal('retreat',header('YOUR ARMY IS IN THE FIELD','End this battle?')+`<div class="modal-body"><p class="modal-intro">Keep the loot earned so far and return home. Troops already deployed will be spent.</p><div class="panel-actions"><button class="btn" data-action="close" style="flex:1">Keep fighting</button><button class="btn btn-gold" data-action="confirm-retreat" style="flex:1">Return with loot</button></div></div>`);});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(modalKind==='result')home();else closeModal();}}});
modal.addEventListener('cancel',e=>{e.preventDefault();if(modalKind==='result')home();else closeModal();});
document.addEventListener('keydown',e=>{if(modal.open||['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Enter'&&placement){confirmPlacement();return;}if(e.key==='Escape'){cancelPlacement();deselect();}if(e.key==='+'||e.key==='=')world.setZoom(world.zoom*1.1);if(e.key==='-')world.setZoom(world.zoom/1.1);if(e.key.toLowerCase()==='h')world.recenter();if(!battle&&e.key.toLowerCase()==='b')openBuild();if(!battle&&e.key.toLowerCase()==='a')openArmy();if(battle&&['1','2','3'].includes(e.key)){selectedTroop=['guardian','ranger','giant'][Number(e.key)-1];spellMode=false;renderDeploy();}});
window.addEventListener('pagehide',()=>{if(!api.online){R.ensure(state);state.raids.lastSeenAt=Date.now();}save();});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
function graphicsError(message){$('loading').hidden=false;$('loading').classList.remove('fade');$('loading').innerHTML=`<div class="critical-error">${icon('monitor')}<p>${message}</p><button class="btn btn-gold" id="reload-game">Reload game</button></div>`;$('reload-game').addEventListener('click',()=>location.reload());icons();}
try{
  const initial=await api.connect();if(!initial){R.ensure(state);const incoming=R.simulateDefense(state);if(incoming)setTimeout(()=>toast('Your village was raided. Open Battle history for details.'),1500);state.raids.lastSeenAt=Date.now();}if(initial){state=initial.state;state.playerId=initial.user.id;try{state.settings={...state.settings,...JSON.parse(storage.getItem('emberfall.preferences')||'{}')};}catch{}battle=initial.battle;battleId=initial.battleId;if(battle)battle.id=battleId;}
  world=new World($('world'),{click:handleClick,notice:toast,hover:id=>{hovered=id;},placement:p=>{$('confirm-placement').disabled=!p.valid;$('placement-text').textContent=(p.valid?'✓ ':'Blocked · ')+TYPES[p.type].name+' · '+p.x+', '+p.z;},frame,error:graphicsError});installModelPictures(world);features=new Features({api,state:()=>village(),root:()=>state,battle:()=>battle,modalKind:()=>modalKind,showModal,header,toast,mutate,apply:applyResponse,sync,startBattle,closeModal,selectHero:k=>{selectedTroop=k;spellMode=false;renderDeploy();},selectSpell:k=>{selectedSpell=k;spellMode=true;closeModal();renderDeploy();}});extensions=new ExpansionUI({api,root:()=>state,showModal,header,toast,mutate,setRealm,setCapital,portrait:(canvas,type,level)=>world.paintPortrait(canvas,type,level),startMode:extra=>startBattle(0,null,extra),selectSiege:k=>{selectedTroop=k;spellMode=false;renderDeploy();}});features.heroes=()=>extensions.heroes();villageUI=new VillageUI({api,world,root:()=>state,village,realm:()=>currentRealm,battle:()=>battle,placing:()=>!!placement,modalKind:()=>modalKind,showModal,header,toast,mutate,closeModal,startFlag});raidUI=new RaidUI({api,root:()=>state,battle:()=>battle,features,showModal,header,toast,mutate,startBattle,home,campaign:openCampaign});new AccountUI(features);quality=new QualityUI({api,root:()=>state,village,realm:()=>currentRealm,showModal,header,toast,mutate,apply:applyResponse,sync});worldSync(true);if(battle)showBattleHUD();world.setQuality(state.settings.quality==='low'?'smooth':state.settings.quality);renderHUD();icons();$('sound-button').innerHTML=icon(state.settings.sound?'volume-2':'volume-x');icons();save();
  setTimeout(()=>{$('loading').classList.add('fade');setTimeout(()=>$('loading').hidden=true,650);},300);
  if(new URLSearchParams(location.search).get('purchase')==='success')toast('Checking payment confirmation. Your gem balance will update automatically.');
  setTimeout(()=>{if(!village().stats.built&&!village().stats.wins)toast('Welcome, chief. Tap a building to upgrade — or Battle to raid.');},1300);
}catch(err){console.error(err);graphicsError(escapeHtml(err.message||'Could not start the game. Reload in a browser with WebGL enabled.'));}

document.addEventListener('change',e=>{if(e.target.id==='graphics-quality'){state.settings.quality=graphicsProfile(e.target.value);world.setQuality(state.settings.quality);save();}});
const kingdomMenu=document.getElementById('kingdom-menu'),nav=document.querySelector('.feature-nav'),navHome=nav.parentElement,navNext=nav.nextSibling;
function arrangeKingdom(){if(document.documentElement.classList.contains('game-compact'))kingdomMenu.querySelector('.kingdom-menu-body').append(nav);else{kingdomMenu.close();navHome.insertBefore(nav,navNext);}}
for(const b of nav.querySelectorAll('button'))if(!b.querySelector('span')){const label=document.createElement('span');label.textContent=b.id==='clans-button'?'Clans':b.id==='research-button'?'Research':b.id==='spells-button'?'Spells':'Season';b.append(label);}
window.addEventListener('gameviewportchange',arrangeKingdom);arrangeKingdom();
document.getElementById('kingdom-button').addEventListener('click',()=>{closeModal();kingdomMenu.showModal();});document.getElementById('close-kingdom').addEventListener('click',()=>kingdomMenu.close());
